import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";
import "bootstrap/dist/css/bootstrap.min.css";

const AvaliacoesSubmetidas = () => {
  const { cursoId } = useParams(); // pega o ID do curso da URL
  const [submissoes, setSubmissoes] = useState([]);

  useEffect(() => {
    const fetchSubmissoes = async () => {
      try {
        const res = await private_api.get(`/cursos/${cursoId}/submissoes`);
        setSubmissoes(res.data);
      } catch (error) {
        console.error("Erro ao buscar submissões:", error);
      }
    };

    fetchSubmissoes();
  }, [cursoId]);

  return (
    <div className="container mt-5">
      <h2 className="mb-4">Avaliações Submetidas dos Alunos</h2>
      {submissoes.length > 0 ? (
        <table className="table table-bordered table-striped">
          <thead className="table-dark">
            <tr>
              <th>Aluno</th>
              <th>Título da Avaliação</th>
              <th>Pontuação</th>
              <th>Tempo</th>
              <th>Data de Submissão</th>
            </tr>
          </thead>
          <tbody>
            {submissoes.map((sub) => (
              <tr key={sub.id}>
                <td>{sub.nomeAluno}</td>
                <td>{sub.titulo}</td>
                <td>{sub.pontuacao}</td>
                <td>{sub.tempo}</td>
                <td>{new Date(sub.dataSubmissao).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>Nenhuma submissão registrada para este curso.</p>
      )}
    </div>
  );
};

export default AvaliacoesSubmetidas;
